// Pinwheel variant (10 tiles)

// 2025-1-26 22:57:17 2025-1-26 23:25:02
// pinwheel

#define C(a,b) ((a).x*(b).y-(a).y*(b).x)
#define P(no, n1, a, u) (C(a-no, n1-no)*C(u-no, n1-no)>0.)

void mainImage( out vec4 O, vec2 U)
{
        O = vec4(0);
        vec2 R = iResolution.xy,
             u = U / R.y, v;

        vec2 a, b, c, d, e, f, g, na, nb, nc;


        float i, T, x = 6., y = 3., k =y*y/(x*x+y*y);

        a.x = x, b.y =y;


        for(i=0.; i<5.; i++)
        {
                //if(T<.5){

                        d = (a-b)*k+b;
                        f = (a+d)*.5;
                        e = (a+c)*.5;
                        g = (c+d)*.5;
                        if(P(f,e, a,u)){// 最左
                                T=0., na = a, nb= e, nc=f;
                        }else if(P(d,c,b,u)){//最右
                                T=1., na = c, nb = b, nc=d; // 对画线有用
                        }else if(P(e,g,c,u)){//左上
                                T=4., na = e, nb=c, nc=g;
                        }else if(P(e,d,f,u)){//中左下
                                T=2., na =d, nb= e, nc=f;
                        }else{// 中右上
                                T=3., na =e, nb=d, nc=g;
                        }
                //}
                a=na, b=nb, c=nc;
        }
        float dist = abs(C(u-b, normalize(a-b)));
        dist = min(dist, abs(C(u-b,normalize(c-b))));
        dist = min(dist, abs(C(u-c,normalize(a-c))));

        k = pow(k, i*.5);

        dist /= k;

        O = vec4( smoothstep( .2 , 0., dist ) );
        if(T==0.){
                O.xy+=.4;
        }else if(T==1.){
                O.x+=.4;
        }else if(T==2.){
                O.x +=.6;
        }else if(T==3.){
                O.xy += vec2(.8, .4);
        }else{
                O.xyz+=vec3(.4,.4,.7);
        }
}
